-- 0030_security_hardening.sql
-- P0 tenant/role hardening for the priority-feature RPCs (0024/0026/0028),
-- view tenant leaks (0023/0027), notification spoofing and the acct() helper.
-- Generated by patching the exact 0024/0026/0028 definitions; only guards were added.

-- ============================================================
-- 1) Views: enforce caller RLS (no cross-tenant leaks)
-- =========================================================
ALTER VIEW public.dealer_outstanding SET (security_invoker = true);
ALTER VIEW public.salesman_commission_summary SET (security_invoker = true);
ALTER VIEW public.bank_reconciliation_summary SET (security_invoker = true);
ALTER VIEW public.team_activity_feed SET (security_invoker = true);
ALTER VIEW public.user_task_summary SET (security_invoker = true);
ALTER VIEW public.unread_notifications_count SET (security_invoker = true);
-- With security_invoker the caller must also hold SELECT on the view itself.
GRANT SELECT ON public.dealer_outstanding TO authenticated;
GRANT SELECT ON public.salesman_commission_summary TO authenticated;
GRANT SELECT ON public.bank_reconciliation_summary TO authenticated;
GRANT SELECT ON public.team_activity_feed TO authenticated;
GRANT SELECT ON public.user_task_summary TO authenticated;
GRANT SELECT ON public.unread_notifications_count TO authenticated;
GRANT SELECT ON public.dealer_outstanding TO service_role;
GRANT SELECT ON public.salesman_commission_summary TO service_role;
GRANT SELECT ON public.bank_reconciliation_summary TO service_role;
GRANT SELECT ON public.team_activity_feed TO service_role;
GRANT SELECT ON public.user_task_summary TO service_role;
GRANT SELECT ON public.unread_notifications_count TO service_role;

-- ============================================================
-- 2) Drop broken priority functions (referenced nowhere)
-- ===========================================================
DROP FUNCTION IF EXISTS public.update_dealer_credit_on_sale(uuid, uuid, numeric, numeric, numeric);
DROP FUNCTION IF EXISTS public.update_dealer_credit_on_payment(uuid, uuid, numeric);
DROP FUNCTION IF EXISTS public.calculate_commission_for_sale(uuid, uuid, uuid);
DROP FUNCTION IF EXISTS public.calculate_product_commission(uuid, uuid, uuid, uuid, integer, numeric);

-- 0030 part: scoped helper
CREATE OR REPLACE FUNCTION public.acct(_biz uuid, _code text) RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT id FROM public.accounts WHERE business_id = _biz AND code = _code AND public.is_member(_biz)
$$;

-- 0030: notification spoofing fix (was is_member only)
DROP POLICY IF EXISTS user_notifications_insert ON public.user_notifications;
CREATE POLICY user_notifications_insert ON public.user_notifications
  FOR INSERT WITH CHECK (
    public.is_member(business_id)
    AND (user_id = auth.uid() OR public.has_biz_role(business_id, ARRAY['owner','manager']::public.member_role[]))
  );

