CREATE OR REPLACE FUNCTION public.update_import_job(
  _job_id uuid,
  _success_records integer,
  _failed_records integer,
  _errors text[],
  _status text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.import_jobs j
    WHERE j.id = _job_id
      AND public.has_biz_role(j.business_id, ARRAY['owner','manager','accountant']::public.member_role[])
  ) THEN
    RAISE EXCEPTION 'You are not authorized for this import.' USING ERRCODE = '42501';
  END IF;
  UPDATE import_jobs
  SET 
    success_records = success_records + _success_records,
    failed_records = failed_records + _failed_records,
    errors = COALESCE(errors, '{}') || _errors,
    status = _status,
    processed_at = now()
  WHERE id = _job_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.check_dealer_credit_limit(
  _biz uuid,
  _customer_id uuid,
  _sale_amount numeric
)
RETURNS TABLE (
  can_sale boolean,
  current_due numeric,
  credit_limit numeric,
  available_credit numeric,
  message text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  current_due numeric;
  credit_limit numeric;
  available_credit numeric;
BEGIN
  IF NOT public.is_member(_biz) THEN
    RAISE EXCEPTION 'You do not have access to this business.' USING ERRCODE = '42501';
  END IF;
  SELECT COALESCE(current_due, 0), COALESCE(credit_limit, 0)
  INTO current_due, credit_limit
  FROM dealer_credit
  WHERE business_id = _biz AND customer_id = _customer_id;

  available_credit := credit_limit - current_due;

  RETURN QUERY
  SELECT 
    available_credit >= _sale_amount,
    current_due,
    credit_limit,
    available_credit,
    CASE 
      WHEN credit_limit = 0 THEN 'No credit limit set'
      WHEN available_credit < _sale_amount THEN 
        'Credit limit exceeded. Available: ' || available_credit || ', Required: ' || _sale_amount
      ELSE 'OK'
    END;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_bank_reconciliation_summary(
  _biz uuid,
  _account_id uuid,
  _from_date date,
  _to_date date
)
RETURNS TABLE (
  recon_id uuid,
  account_id uuid,
  reconciliation_date date,
  statement_balance numeric,
  book_balance numeric,
  difference numeric,
  status text,
  created_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_member(_biz) THEN
    RAISE EXCEPTION 'You do not have access to this business.' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT 
    r.id as recon_id,
    r.account_id,
    r.reconciliation_date,
    r.statement_balance,
    r.book_balance,
    r.difference,
    r.status,
    r.created_at
  FROM bank_reconciliations r
  WHERE r.business_id = _biz
    AND r.account_id = COALESCE(_account_id, r.account_id)
    AND r.reconciliation_date BETWEEN _from_date AND _to_date
  ORDER BY r.reconciliation_date DESC;
END;
$$;

CREATE OR REPLACE FUNCTION public.request_transfer_approval(
  _transfer_id uuid,
  _notes text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  transfer_rec stock_transfers%ROWTYPE;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.stock_transfers t
    WHERE t.id = _transfer_id AND public.is_member(t.business_id)
  ) THEN
    RAISE EXCEPTION 'You do not have access to this business.' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO transfer_rec
  FROM stock_transfers
  WHERE id = _transfer_id;

  IF transfer_rec IS NULL THEN
    RAISE EXCEPTION 'Transfer not found';
  END IF;

  IF transfer_rec.status != 'draft' THEN
    RAISE EXCEPTION 'Transfer must be in draft status';
  END IF;

  UPDATE stock_transfers
  SET 
    status = 'pending_approval',
    notes = COALESCE(_notes, notes),
    updated_at = now()
  WHERE id = _transfer_id;

  INSERT INTO stock_transfer_approvals (
    business_id, transfer_id, action, approved_by, comments
  ) VALUES (
    transfer_rec.business_id, _transfer_id, 'request_change', 
    auth.uid(), 'Approval requested'
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.approve_stock_transfer(
  _transfer_id uuid,
  _comments text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  transfer_rec stock_transfers%ROWTYPE;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.stock_transfers t
    WHERE t.id = _transfer_id
      AND public.has_biz_role(t.business_id, ARRAY['owner','manager','branch_manager']::public.member_role[])
  ) THEN
    RAISE EXCEPTION 'You are not authorized to approve transfers.' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO transfer_rec
  FROM stock_transfers
  WHERE id = _transfer_id;

  IF transfer_rec IS NULL THEN
    RAISE EXCEPTION 'Transfer not found';
  END IF;

  IF transfer_rec.status != 'pending_approval' THEN
    RAISE EXCEPTION 'Transfer must be pending approval';
  END IF;

  UPDATE stock_transfers
  SET 
    status = 'approved',
    approved_by = auth.uid(),
    approved_at = now(),
    updated_at = now()
  WHERE id = _transfer_id;

  INSERT INTO stock_transfer_approvals (
    business_id, transfer_id, action, approved_by, comments
  ) VALUES (
    transfer_rec.business_id, _transfer_id, 'approve', 
    auth.uid(), _comments
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.reject_stock_transfer(
  _transfer_id uuid,
  _reason text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  transfer_rec stock_transfers%ROWTYPE;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.stock_transfers t
    WHERE t.id = _transfer_id
      AND public.has_biz_role(t.business_id, ARRAY['owner','manager','branch_manager']::public.member_role[])
  ) THEN
    RAISE EXCEPTION 'You are not authorized to approve transfers.' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO transfer_rec
  FROM stock_transfers
  WHERE id = _transfer_id;

  IF transfer_rec IS NULL THEN
    RAISE EXCEPTION 'Transfer not found';
  END IF;

  IF transfer_rec.status != 'pending_approval' THEN
    RAISE EXCEPTION 'Transfer must be pending approval';
  END IF;

  IF _reason IS NULL OR trim(_reason) = '' THEN
    RAISE EXCEPTION 'Rejection reason is required';
  END IF;

  UPDATE stock_transfers
  SET 
    status = 'draft',
    rejected_by = auth.uid(),
    rejected_at = now(),
    rejection_reason = _reason,
    updated_at = now()
  WHERE id = _transfer_id;

  INSERT INTO stock_transfer_approvals (
    business_id, transfer_id, action, approved_by, comments
  ) VALUES (
    transfer_rec.business_id, _transfer_id, 'reject', 
    auth.uid(), _reason
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.get_pending_transfer_approvals(
  _biz uuid
)
RETURNS TABLE (
  transfer_id uuid,
  from_branch_name text,
  to_branch_name text,
  item_count integer,
  total_value numeric,
  requested_by text,
  requested_at timestamptz,
  notes text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_member(_biz) THEN
    RAISE EXCEPTION 'You do not have access to this business.' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT 
    st.id as transfer_id,
    fb.name as from_branch_name,
    tb.name as to_branch_name,
    COUNT(sti.id)::integer as item_count,
    COALESCE(SUM(sti.qty * pv.purchase_price), 0) as total_value,
    u.raw_user_meta_data->>'full_name' as requested_by,
    st.created_at as requested_at,
    st.notes
  FROM stock_transfers st
  JOIN branches fb ON fb.id = st.from_branch_id
  JOIN branches tb ON tb.id = st.to_branch_id
  JOIN stock_transfer_items sti ON sti.transfer_id = st.id
  JOIN product_variants pv ON pv.id = sti.variant_id
  LEFT JOIN auth.users u ON u.id = st.created_by
  WHERE st.business_id = _biz
    AND st.status = 'pending_approval'
  GROUP BY st.id, fb.name, tb.name, u.raw_user_meta_data, st.created_at, st.notes
  ORDER BY st.created_at DESC;
END;
$$;

CREATE OR REPLACE FUNCTION public.create_export_job(
  _biz uuid,
  _export_type text,
  _format text,
  _filters jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  job_id uuid;
  file_name text;
BEGIN
  IF NOT public.has_biz_role(_biz, ARRAY['owner', 'manager', 'accountant']::public.member_role[]) THEN
    RAISE EXCEPTION 'You are not authorized for this action.' USING ERRCODE = '42501';
  END IF;
  file_name := _export_type || '_' || 
               to_char(now(), 'YYYY-MM-DD_HH24-MI-SS') || 
               '.' || _format;

  INSERT INTO export_jobs (
    business_id, export_type, format, filters, file_name, status
  ) VALUES (
    _biz, _export_type, _format, _filters, file_name, 'pending'
  )
  RETURNING id INTO job_id;

  RETURN job_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.update_export_job_status(
  _job_id uuid,
  _status text,
  _file_url text DEFAULT NULL,
  _record_count integer DEFAULT NULL,
  _file_size bigint DEFAULT NULL,
  _error_message text DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.export_jobs j
    WHERE j.id = _job_id
      AND public.has_biz_role(j.business_id, ARRAY['owner','manager','accountant']::public.member_role[])
  ) THEN
    RAISE EXCEPTION 'You are not authorized for this export.' USING ERRCODE = '42501';
  END IF;
  UPDATE export_jobs
  SET 
    status = _status,
    file_url = COALESCE(_file_url, file_url),
    record_count = COALESCE(_record_count, record_count),
    file_size = COALESCE(_file_size, file_size),
    error_message = _error_message,
    completed_at = CASE WHEN _status IN ('completed', 'failed') THEN now() ELSE completed_at END
  WHERE id = _job_id;
END;
$$;

