$$;

CREATE OR REPLACE FUNCTION public.get_active_subscriptions(
  _biz uuid
)
RETURNS TABLE (
  channel text,
  subscriber_count bigint,
  last_activity timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_member(_biz) THEN
    RAISE EXCEPTION 'You do not have access to this business.' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT 
    rs.channel,
    COUNT(*)::bigint as subscriber_count,
    MAX(rs.last_activity_at) as last_activity
  FROM realtime_subscriptions rs
  WHERE rs.business_id = _biz
    AND rs.last_activity_at > now() - interval '1 hour'
  GROUP BY rs.channel
  ORDER BY subscriber_count DESC;
END;
$$;

CREATE OR REPLACE FUNCTION public.export_customers_json(
  _biz uuid,
  _filters jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.has_biz_role(_biz, ARRAY['owner', 'manager', 'accountant']::public.member_role[]) THEN
    RAISE EXCEPTION 'You are not authorized for this action.' USING ERRCODE = '42501';
  END IF;
  RETURN COALESCE(
    (SELECT jsonb_agg(to_jsonb(c) ORDER BY c.name)
     FROM customers c
     WHERE c.business_id = _biz
       AND c.status = 'active'),
    '[]'::jsonb
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.export_products_json(
  _biz uuid,
  _filters jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.has_biz_role(_biz, ARRAY['owner', 'manager', 'accountant']::public.member_role[]) THEN
    RAISE EXCEPTION 'You are not authorized for this action.' USING ERRCODE = '42501';
  END IF;
  RETURN COALESCE(
    (SELECT jsonb_agg(
       jsonb_build_object(
         'sku', v.sku,
         'product', p.model,
         'brand', b.name,
         'category', c.name,
         'ram', v.ram,
         'storage', v.storage,
         'color', v.color,
         'purchase_price', v.purchase_price,
         'retail_price', v.retail_price,
         'status', v.status
       ) ORDER BY v.sku
     )
     FROM product_variants v
     JOIN products p ON p.id = v.product_id
     JOIN brands b ON b.id = p.brand_id
     JOIN categories c ON c.id = p.category_id
     WHERE v.business_id = _biz
       AND v.status = 'active'),
    '[]'::jsonb
  );
END;
$$;

