CREATE OR REPLACE FUNCTION public.create_task(
  _biz uuid,
  _title text,
  _description text,
  _assigned_to uuid,
  _priority text DEFAULT 'medium',
  _due_date date DEFAULT NULL,
  _entity_type text DEFAULT NULL,
  _entity_id uuid DEFAULT NULL
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  task_id uuid;
BEGIN
  IF NOT public.is_member(_biz) THEN
    RAISE EXCEPTION 'You do not have access to this business.' USING ERRCODE = '42501';
  END IF;
  INSERT INTO tasks (
    business_id, title, description, assigned_to, created_by, priority, due_date, entity_type, entity_id
  ) VALUES (
    _biz, _title, _description, _assigned_to, auth.uid(), _priority, _due_date, _entity_type, _entity_id
  )
  RETURNING id INTO task_id;
  IF _assigned_to IS NOT NULL THEN
    PERFORM create_notification(
      _biz,
      _assigned_to,
      'New Task Assigned',
      _title,
      'task',
      '/app/tasks/' || task_id
    );
  END IF;
  RETURN task_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.update_task_status(
  _task_id uuid,
  _status text
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.tasks t
    WHERE t.id = _task_id AND public.is_member(t.business_id)
  ) THEN
    RAISE EXCEPTION 'You do not have access to this task.' USING ERRCODE = '42501';
  END IF;
  UPDATE tasks
  SET 
    status = _status,
    completed_at = CASE WHEN _status = 'completed' THEN now() ELSE NULL END,
    completed_by = CASE WHEN _status = 'completed' THEN auth.uid() ELSE NULL END,
    updated_at = now()
  WHERE id = _task_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_user_tasks(
  _biz uuid,
  _user_id uuid DEFAULT NULL,
  _status text DEFAULT NULL
)
RETURNS TABLE (
  id uuid,
  title text,
  description text,
  assigned_to uuid,
  assigned_to_name text,
  created_by uuid,
  created_by_name text,
  priority text,
  status text,
  due_date date,
  entity_type text,
  entity_id uuid,
  created_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_member(_biz) THEN
    RAISE EXCEPTION 'You do not have access to this business.' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT 
    t.id,
    t.title,
    t.description,
    t.assigned_to,
    u1.raw_user_meta_data->>'full_name' as assigned_to_name,
    t.created_by,
    u2.raw_user_meta_data->>'full_name' as created_by_name,
    t.priority,
    t.status,
    t.due_date,
    t.entity_type,
    t.entity_id,
    t.created_at
  FROM tasks t
  LEFT JOIN auth.users u1 ON u1.id = t.assigned_to
  LEFT JOIN auth.users u2 ON u2.id = t.created_by
  WHERE t.business_id = _biz
    AND (_user_id IS NULL OR t.assigned_to = _user_id)
    AND (_status IS NULL OR t.status = _status)
  ORDER BY 
    CASE t.priority
      WHEN 'urgent' THEN 1
      WHEN 'high' THEN 2
      WHEN 'medium' THEN 3
      WHEN 'low' THEN 4
    END,
    t.due_date NULLS LAST,
    t.created_at DESC;
END;
$$;

