CREATE OR REPLACE FUNCTION public.generate_customer_portal_token(
  _biz uuid,
  _customer_id uuid,
  _expires_in_days integer DEFAULT 30
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  token_value text;
BEGIN
  IF NOT public.has_biz_role(_biz, ARRAY['owner', 'manager', 'accountant']::public.member_role[]) THEN
    RAISE EXCEPTION 'You are not authorized for this action.' USING ERRCODE = '42501';
  END IF;
  token_value := encode(gen_random_bytes(32), 'base64');
  INSERT INTO customer_portal_tokens (
    business_id, customer_id, token, expires_at
  ) VALUES (
    _biz, _customer_id, token_value, now() + (_expires_in_days || ' days')::interval
  );
  RETURN token_value;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_customer_portal_data(
  _biz uuid,
  _customer_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  result jsonb;
  customer_info jsonb;
  recent_sales jsonb;
  total_due numeric;
BEGIN
  IF NOT public.is_member(_biz) THEN
    RAISE EXCEPTION 'You do not have access to this business.' USING ERRCODE = '42501';
  END IF;
  SELECT to_jsonb(c.*) INTO customer_info
  FROM customers c
  WHERE c.id = _customer_id AND c.business_id = _biz;
  SELECT jsonb_agg(s.*) INTO recent_sales
  FROM (
    SELECT id, invoice_no, sale_date, total, paid, due
    FROM sales
    WHERE customer_id = _customer_id AND business_id = _biz
    ORDER BY sale_date DESC
    LIMIT 10
  ) s;
  SELECT COALESCE(SUM(due), 0) INTO total_due
  FROM sales
  WHERE customer_id = _customer_id AND business_id = _biz;
  result := jsonb_build_object(
    'customer', customer_info,
    'recent_sales', COALESCE(recent_sales, '[]'::jsonb),
    'total_due', total_due
  );
  RETURN result;
END;
$$;

CREATE OR REPLACE FUNCTION public.create_payment_request(
  _biz uuid,
  _customer_id uuid,
  _amount numeric,
  _due_date date,
  _description text
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  request_id uuid;
BEGIN
  IF NOT public.has_biz_role(_biz, ARRAY['owner', 'manager', 'accountant']::public.member_role[]) THEN
    RAISE EXCEPTION 'You are not authorized for this action.' USING ERRCODE = '42501';
  END IF;
  INSERT INTO customer_payment_requests (
    business_id, customer_id, amount, due_date, description, created_by
  ) VALUES (
    _biz, _customer_id, _amount, _due_date, _description, auth.uid()
  )
  RETURNING id INTO request_id;
  RETURN request_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.save_report_config(
  _biz uuid,
  _name text,
  _description text,
  _report_type text,
  _filters jsonb,
  _columns jsonb,
  _sort_by jsonb,
  _is_public boolean DEFAULT false
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  report_id uuid;
BEGIN
  IF NOT public.is_member(_biz) THEN
    RAISE EXCEPTION 'You do not have access to this business.' USING ERRCODE = '42501';
  END IF;
  INSERT INTO saved_reports (
    business_id, user_id, name, description, report_type, filters, columns, sort_by, is_public
  ) VALUES (
    _biz, auth.uid(), _name, _description, _report_type, _filters, _columns, _sort_by, _is_public
  )
  RETURNING id INTO report_id;
  RETURN report_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_saved_reports(
  _biz uuid,
  _report_type text DEFAULT NULL
)
RETURNS TABLE (
  id uuid,
  name text,
  description text,
  report_type text,
  filters jsonb,
  columns jsonb,
  is_public boolean,
  user_id uuid,
  user_name text,
  created_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_member(_biz) THEN
    RAISE EXCEPTION 'You do not have access to this business.' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT 
    sr.id,
    sr.name,
    sr.description,
    sr.report_type,
    sr.filters,
    sr.columns,
    sr.is_public,
    sr.user_id,
    u.raw_user_meta_data->>'full_name' as user_name,
    sr.created_at
  FROM saved_reports sr
  LEFT JOIN auth.users u ON u.id = sr.user_id
  WHERE sr.business_id = _biz
    AND (_report_type IS NULL OR sr.report_type = _report_type)
    AND (sr.user_id = auth.uid() OR sr.is_public = true)
  ORDER BY sr.created_at DESC;
END;
$$;

CREATE OR REPLACE FUNCTION public.record_kpi_snapshot(
  _biz uuid,
  _snapshot_date date,
  _kpi_type text,
  _value numeric,
  _metadata jsonb DEFAULT '{}'
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.has_biz_role(_biz, ARRAY['owner', 'manager', 'accountant']::public.member_role[]) THEN
    RAISE EXCEPTION 'You are not authorized for this action.' USING ERRCODE = '42501';
  END IF;
  INSERT INTO kpi_snapshots (
    business_id, snapshot_date, kpi_type, value, metadata
  ) VALUES (
    _biz, _snapshot_date, _kpi_type, _value, _metadata
  )
  ON CONFLICT (business_id, snapshot_date, kpi_type) 
  DO UPDATE SET value = _value, metadata = _metadata;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_kpi_trend(
  _biz uuid,
  _kpi_type text,
  _from_date date,
  _to_date date
)
RETURNS TABLE (
  snapshot_date date,
  value numeric,
  metadata jsonb
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_member(_biz) THEN
    RAISE EXCEPTION 'You do not have access to this business.' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
  SELECT 
    ks.snapshot_date,
    ks.value,
    ks.metadata
  FROM kpi_snapshots ks
  WHERE ks.business_id = _biz
    AND ks.kpi_type = _kpi_type
    AND ks.snapshot_date BETWEEN _from_date AND _to_date
  ORDER BY ks.snapshot_date ASC;
END;
$$;

-- =====================================================
-- 3) Explicit function privileges (ACL)
-- =====================================================

DO $$
DECLARE
  auth_names text[] := ARRAY['add_entity_comment', 'approve_stock_transfer', 'check_dealer_credit_limit', 'complete_backup', 'complete_bank_reconciliation', 'create_attachment', 'create_backup_schedule', 'create_export_job', 'create_import_job', 'create_notification', 'create_payment_request', 'create_task', 'delete_attachment', 'export_customers_json', 'export_products_json', 'fail_backup', 'generate_customer_portal_token', 'get_active_subscriptions', 'get_attachments_for_record', 'get_bank_reconciliation_summary', 'get_customer_portal_data', 'get_entity_comments', 'get_export_job_status', 'get_kpi_trend', 'get_pending_transfer_approvals', 'get_salesman_commission_summary', 'get_saved_reports', 'get_team_activity', 'get_user_notifications', 'get_user_tasks', 'log_user_activity', 'mark_all_notifications_read', 'mark_notification_read', 'mark_reconciliation_item_cleared', 'pay_salesman_commission', 'record_kpi_snapshot', 'reject_stock_transfer', 'request_transfer_approval', 'save_report_config', 'start_backup', 'start_bank_reconciliation', 'subscribe_realtime_channel', 'unsubscribe_realtime_channel', 'update_export_job_status', 'update_import_job', 'update_task_status']::text[];
  internal_names text[] := ARRAY['clean_expired_backups', 'generate_daily_kpi_snapshots', 'verify_customer_portal_token']::text[];
  r record;
BEGIN
  FOR r IN
    SELECT p.proname, pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = ANY (auth_names || internal_names)
  LOOP
    IF r.proname = ANY (internal_names) THEN
      EXECUTE format('REVOKE ALL ON FUNCTION public.%I(%s) FROM PUBLIC, anon, authenticated', r.proname, r.args);
      EXECUTE format('GRANT EXECUTE ON FUNCTION public.%I(%s) TO service_role', r.proname, r.args);
    ELSE
      EXECUTE format('REVOKE ALL ON FUNCTION public.%I(%s) FROM PUBLIC, anon', r.proname, r.args);
      EXECUTE format('GRANT EXECUTE ON FUNCTION public.%I(%s) TO authenticated', r.proname, r.args);
    END IF;
  END LOOP;
END $$;

-- sanitise the old account-helper grant
REVOKE ALL ON FUNCTION public.acct(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.acct(uuid, text) TO authenticated;

